function percerLeCode(message) {
  const alphabet = "abcdefghijklmnopqrstuvwxyz";
  const compte = {};
  let frequente = "";
  for (const caractere of message) {
    if (alphabet.includes(caractere)) {
      compte[caractere] = (compte[caractere] || 0) + 1;
      if (frequente === "" || compte[caractere] > compte[frequente]) {
        frequente = caractere;
      }
    }
  }
  if (frequente === "") {
    return message;
  }
  const decalage = (alphabet.indexOf(frequente) - alphabet.indexOf("e") + 26) % 26;
  let clair = "";
  for (const caractere of message) {
    const position = alphabet.indexOf(caractere);
    if (position === -1) {
      clair = clair + caractere;
    } else {
      clair = clair + alphabet[(position - decalage + 26) % 26];
    }
  }
  return clair;
}

