function casserVigenere(message, longueur) {
  const alphabet = "abcdefghijklmnopqrstuvwxyz";
  const colonnes = [];
  for (let i = 0; i < longueur; i++) {
    colonnes.push(new Array(26).fill(0));
  }
  let rang = 0;
  for (const c of message) {
    const p = alphabet.indexOf(c);
    if (p !== -1) {
      colonnes[rang % longueur][p]++;
      rang++;
    }
  }
  const decalages = colonnes.map((freq) => {
    let meilleur = 0;
    let decalage = 0;
    for (let p = 0; p < 26; p++) {
      const d = (p - 4 + 26) % 26;
      if (freq[p] > meilleur || (freq[p] === meilleur && freq[p] > 0 && d < decalage)) {
        meilleur = freq[p];
        decalage = d;
      }
    }
    return decalage;
  });
  let clair = "";
  rang = 0;
  for (const c of message) {
    const p = alphabet.indexOf(c);
    if (p === -1) {
      clair += c;
    } else {
      clair += alphabet[(p - decalages[rang % longueur] + 26) % 26];
      rang++;
    }
  }
  return clair;
}

