def casser_vigenere(message, longueur):
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    colonnes = [[0] * 26 for _ in range(longueur)]
    rang = 0
    for c in message:
        p = alphabet.find(c)
        if p != -1:
            colonnes[rang % longueur][p] += 1
            rang += 1
    decalages = []
    for freq in colonnes:
        meilleur = 0
        decalage = 0
        for p in range(26):
            d = (p - 4) % 26
            if freq[p] > meilleur or (freq[p] == meilleur and freq[p] > 0 and d < decalage):
                meilleur = freq[p]
                decalage = d
        decalages.append(decalage)
    clair = ""
    rang = 0
    for c in message:
        p = alphabet.find(c)
        if p == -1:
            clair += c
        else:
            clair += alphabet[(p - decalages[rang % longueur]) % 26]
            rang += 1
    return clair

